        {
            ExecutionStatus.Succeeded => "→ succeeds",
            ExecutionStatus.Failed    => "→ failed",
            ExecutionStatus.Suspended => "→ suspended",
            _ => throw new ArgumentOutOfRangeException(nameof(status)),
        });
    }

