    /// <summary>
    /// Recursive term printer with cycle detection.
    /// <para>
    /// Three branches: ConstTerm (nil → []); list-shaped StructTerm (functor '.', arity 2 →
    /// Prolog-style [h, …]); other StructTerm (functor(arg, …)).
    /// For VarRef args: dereferences via engine.Runtime.Heap; labels unbound vars Xn? (reader)
    /// or Xn (writer); tracks visited addresses in <paramref name="path"/> to detect &lt;circular&gt;.
    /// </para>
    /// </summary>
    private static string FormatTerm(Term? term, GlpEngine? engine = null, HashSet<int>? path = null)
    {
        if (term is null) return "[]";

        // Null-coalescing assignment: Dart `path ??= <int>{};` → C# `path ??= new HashSet<int>();`
        path ??= new HashSet<int>();

        // ── ConstTerm branch ──────────────────────────────────────────────────
        if (term is ConstTerm c)
        {
            // Dart loose `term.value == 'nil'` works via operator==;
            // C# requires explicit string check because ConstTerm.Value is object?.
            if (c.Value is null || (c.Value is string str && str == "nil"))
                return "[]";
            return c.Value.ToString() ?? string.Empty;
        }

        // ── List-shaped StructTerm branch: functor '.', arity 2 ───────────────
        if (term is StructTerm listSt && listSt.Functor == "." && listSt.Args.Count == 2)
        {
            var elements = new List<string>();
            Term? current = term;

            while (true)
            {
                if (current is not StructTerm cs || cs.Functor != ".")
                    break;

                var head = cs.Args[0];
                var tail = cs.Args[1];

                string headStr;
                if (head is VarRef headVr && engine is not null)
                {
                    var addr = headVr.Addr;
                    if (path.Contains(addr))
                    {
                        headStr = "<circular>";
                    }
                    else
                    {
                        path.Add(addr);
                        var derefHead = engine.Runtime.Heap.Dereference(headVr);
                        if (derefHead is VarRef derefVr)
                        {
                            var displayId = derefVr.Addr;
                            headStr = engine.Runtime.Heap.IsReader(derefVr.Addr)
                                ? $"X{displayId}?"
                                : $"X{displayId}";
                        }
                        else
                        {
                            headStr = FormatTerm(derefHead, engine, path);
                        }
                        path.Remove(addr);
                    }
                }
                else
                {
                    headStr = FormatTerm(head, engine, path);
                }

                elements.Add(headStr);

                // Advance to tail
                if (tail is VarRef tailVr && engine is not null)
                {
                    var addr = tailVr.Addr;
                    if (path.Contains(addr))
                    {
                        var displayId = addr;
                        var label = engine.Runtime.Heap.IsReader(tailVr.Addr)
                            ? $"X{displayId}?"
                            : $"X{displayId}";
                        return $"[{string.Join(", ", elements)} | <circular {label}>]";
                    }
                    path.Add(addr);
                    var derefTail = engine.Runtime.Heap.Dereference(tailVr);
                    if (derefTail is VarRef derefTailVr)
                    {
                        path.Remove(addr);
                        var displayId = derefTailVr.Addr;
                        var label = engine.Runtime.Heap.IsReader(derefTailVr.Addr)
                            ? $"X{displayId}?"
                            : $"X{displayId}";
                        return $"[{string.Join(", ", elements)} | {label}]";
                    }
                    current = derefTail;
                    path.Remove(addr);
                    if (current is not StructTerm)
                        break;
                }
                else if (tail is ConstTerm tailCt &&
                         (tailCt.Value == null || (tailCt.Value is string ts && ts == "nil")))
                {
                    break; // proper list end
                }
                else if (tail is StructTerm tailSt && tailSt.Functor == ".")
                {
                    current = tailSt;
                }
                else
                {
                    break;
                }
            }

            return $"[{string.Join(", ", elements)}]";
        }

        // ── Other StructTerm branch ───────────────────────────────────────────
        if (term is StructTerm s)
        {
            // currentPath shares the same HashSet<int> reference — mutation is visible
            // to recursive calls (mirrors Dart Set<int> reference semantics exactly).
            var currentPath = path;
            var formattedArgs = string.Join(", ", s.Args.Select(arg =>
            {
                if (arg is VarRef argVr && engine is not null)
                {
                    var addr = argVr.Addr;
                    if (currentPath.Contains(addr))
                        return "<circular>";
                    currentPath.Add(addr);
                    var deref = engine.Runtime.Heap.Dereference(argVr);
                    string result;
                    if (deref is VarRef derefVr)
                    {
                        var displayId = derefVr.Addr;
                        result = engine.Runtime.Heap.IsReader(derefVr.Addr)
                            ? $"X{displayId}?"
                            : $"X{displayId}";
                    }
                    else
                    {
                        result = FormatTerm(deref, engine, currentPath);
                    }
                    currentPath.Remove(addr);
                    return result;
                }
                return FormatTerm(arg, engine, currentPath);
            }));
            return $"{s.Functor}({formattedArgs})";
        }

        // Fallback — NRT-aware: object?.ToString() is nullable under .NET NRT
        return term.ToString() ?? string.Empty;
    }

    // ── RunBoot ───────────────────────────────────────────────────────────────

    /// <summary>
    /// Run a multi-isolate boot file via IsolateManager.
    /// <para>
    /// Auto-detects the project directory: if the boot file is under a
    /// <c>mad_boot/</c> directory, projectDir = boot file's grandparent;
    /// otherwise projectDir = boot file's parent.
    /// </para>
    /// </summary>
    private static async Task RunBoot(string bootPath, string rootSelfGlpPath, int timeoutSec)
    {
        // Path.GetFullPath may throw ArgumentException/NotSupportedException/PathTooLongException
        // on illegal paths — equivalent to Dart's File() invalid-path branch.
        string bootPathFull;
        try
        {
            bootPathFull = Path.GetFullPath(bootPath);
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error: invalid boot path: {e.Message}");
            return;
        }

        if (!File.Exists(bootPathFull))
        {
            Console.WriteLine($"Error: boot file not found: {bootPath}");
            return;
        }

        var source = File.ReadAllText(bootPathFull, Encoding.UTF8);
        var loader = new BootLoader();
        BootConfig config;
        try
        {
            config = loader.Load(source);
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error parsing boot file: {e.Message}");
            return;
        }

        // Compute project directory.
        // Dart: parent.uri.pathSegments.where((s) => s.isNotEmpty).lastOrNull == 'mad_boot'
        //   → if the last non-empty path segment of the boot-file's parent dir is "mad_boot",
        //     projectDir = grandparent; else projectDir = parent.
        // C#: Path.GetFileName on a directory path returns the leaf segment
        //     (same trailing-separator robustness as Dart's where-isNotEmpty).
        var parentDir = Path.GetDirectoryName(bootPathFull) ?? string.Empty;
        var projectDir = Path.GetFileName(parentDir) == "mad_boot"
            ? (Path.GetDirectoryName(parentDir) ?? parentDir)
            : parentDir;

        config.ProjectDir = projectDir;
        config.RootSelfGlpPath = rootSelfGlpPath;

        Console.WriteLine($"Booting {config.Directives.Count} isolates from {bootPathFull}");
        Console.WriteLine($"  projectDir: {projectDir}");
        Console.WriteLine($"  agents: {string.Join(", ", config.Directives.Select(d => d.AgentId))}");

        var manager = new IsolateManager();
        // OnUIOutput type is Action<string, Term>? per isolate_manager convspec.
        // The Dart lambda's `message` is dynamic (calls .toString()); C# `Term` renders via Term.ToString().
        manager.OnUIOutput = (agentId, message) =>
            Console.WriteLine($"[{agentId}] {message}");

        try
        {
            await manager.Boot(config);
            manager.Start();
            Console.WriteLine($"✓ Started — running for {timeoutSec}s");
            await Task.Delay(TimeSpan.FromSeconds(timeoutSec));
        }
        catch (Exception e)
        {
            Console.WriteLine($"Boot failed: {e.Message}");
            Console.WriteLine(e.StackTrace);
        }
        finally
        {
            await manager.Shutdown();
            Console.WriteLine("✓ Shutdown complete");
        }
    }

    // ── GetGitCommitAsync ─────────────────────────────────────────────────────

    /// <summary>
    /// Run <c>git log -1 --format="%h %s"</c> and return trimmed stdout on exit 0,
    /// or null if git is absent / not a repo or any exception occurs.
    /// </summary>
    private static async Task<string?> GetGitCommitAsync()
    {
        try
        {
            using var p = new Process
            {
                StartInfo = new ProcessStartInfo("git")
                {
                    RedirectStandardOutput = true,
                    RedirectStandardError  = true,
                    UseShellExecute        = false,
                    CreateNoWindow         = true,
                },
            };
            // ArgumentList is the whitespace-safe replacement for the legacy Arguments string.
            // Each element is one discrete argv entry — %h %s stays ONE argument, verbatim.
            p.StartInfo.ArgumentList.Add("log");
            p.StartInfo.ArgumentList.Add("-1");
            p.StartInfo.ArgumentList.Add("--format=%h %s");
            p.Start();
            // Read stdout BEFORE awaiting exit to avoid the classic full-pipe deadlock.
            var stdout = await p.StandardOutput.ReadToEndAsync();
            await p.WaitForExitAsync();
            if (p.ExitCode == 0)
                return stdout.Trim();
        }
        catch
        {
            // Git not available or not a git repo — swallow silently (mirrors Dart catch(e) {}).
        }
        return null;
    }
